<script>
(() => {
 const branch=document.getElementById('renewal-branch'),site=document.getElementById('renewal-site');
 function syncSites(reset) { if(reset) site.value=''; for(const option of site.options) { const hidden=Boolean(option.value && branch.value && option.dataset.branch!==branch.value); option.hidden=hidden;option.disabled=hidden; } }
 branch.addEventListener('change',()=>syncSites(true));syncSites(false);
 const start=document.getElementById('renewal-month'),end=document.getElementById('renewal-month-end');
 start.addEventListener('change',()=>{ if(Number(end.value)<Number(start.value)) end.value=start.value; });
})();
</script>
